-- 招投标公告(标讯)表
CREATE TABLE IF NOT EXISTS `notice` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '公告编号',
  `title` varchar(512) NOT NULL DEFAULT '' COMMENT '公告标题',
  `type` varchar(16) NOT NULL DEFAULT '' COMMENT '公告类型:tender 招标/win 中标/change 变更/explore 采购',
  `province` varchar(32) NOT NULL DEFAULT '' COMMENT '省份',
  `city` varchar(32) NOT NULL DEFAULT '' COMMENT '城市',
  `industry` varchar(64) NOT NULL DEFAULT '' COMMENT '行业',
  `budget` decimal(18,2) DEFAULT NULL COMMENT '预算金额(万元)',
  `tender_person` varchar(128) NOT NULL DEFAULT '' COMMENT '招标人/采购人',
  `agency` varchar(128) NOT NULL DEFAULT '' COMMENT '代理机构',
  `contact` varchar(64) NOT NULL DEFAULT '' COMMENT '联系人',
  `contact_phone` varchar(32) NOT NULL DEFAULT '' COMMENT '联系电话',
  `content` longtext COMMENT '公告原文(HTML)',
  `source` varchar(128) NOT NULL DEFAULT '' COMMENT '来源网站',
  `publish_time` datetime NOT NULL COMMENT '发布时间',
  `creator` varchar(64) DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint(20) NOT NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`),
  KEY `idx_type_publish` (`type`, `publish_time`),
  KEY `idx_province` (`province`),
  KEY `idx_industry` (`industry`),
  KEY `idx_publish_time` (`publish_time`)
) ENGINE=InnoDB AUTO_INCREMENT=100 DEFAULT CHARSET=utf8mb4 COMMENT='招投标公告';

-- 种子数据(与 user-web mock 一致,供开发联调;正式数据由爬虫写入)
INSERT INTO `notice` (`id`, `title`, `type`, `province`, `city`, `industry`, `budget`, `tender_person`, `agency`, `contact`, `contact_phone`, `content`, `source`, `publish_time`, `creator`, `updater`, `deleted`, `tenant_id`) VALUES
(1, '2026 年市政道路提升改造工程设计施工总承包项目招标公告', 'tender', '湖北省', '武汉市', '市政工程', 12500.00, '武汉市市政建设集团有限公司', '湖北中天招标咨询有限公司', '张工', '027-87654321', '<h3>一、招标条件</h3><p>本项目已由 <strong>武汉市发展和改革委员会</strong> 批准建设,项目资金来源为 <strong>政府投资</strong>,招标人为武汉市市政建设集团有限公司。</p><h3>二、项目概况与招标范围</h3><p>1. 项目名称:2026 年市政道路提升改造工程<br/>2. 招标编号:HBZT-2026-0917<br/>3. 建设地点:武汉市江汉区、武昌区<br/>4. 建设规模:道路改造里程约 8.6 公里,含排水管网提升、人行道铺装、路灯亮化<br/>5. 计划工期:180 日历天<br/>6. 招标范围:设计施工总承包(EPC)</p>', '中国招标投标公共服务平台', '2026-09-07 09:30:00', '', '', b'0', 0),
(2, '武汉市轨道交通 12 号线一期工程土建施工 3 标段中标候选人公示', 'win', '湖北省', '武汉市', '轨道交通', 38600.00, '武汉地铁集团有限公司', '湖北省成套招标股份有限公司', '李经理', '027-88776655', '<h3>中标候选人公示</h3><p>经评标委员会评审,<strong>中铁十一局集团有限公司</strong> 为本项目第一中标候选人,投标报价 38600 万元,评标得分 96.32 分。</p><p>第二中标候选人:中铁六局集团有限公司,报价 38920 万元;<br/>第三中标候选人:中铁二十三局集团有限公司,报价 39100 万元。</p>', '武汉市公共资源交易网', '2026-09-07 08:50:00', '', '', b'0', 0),
(3, '某市人民医院智慧医疗信息化建设项目招标文件变更公告', 'change', '广东省', '深圳市', '医疗卫生', 2600.00, '深圳市人民医院', '广东明正项目管理有限公司', '赵女士', '0755-26551133', '<h3>变更内容</h3><p>1. 原招标公告中"投标截止时间"变更为 <strong>2026 年 9 月 22 日 14:00</strong>;<br/>2. "完成经营库容档案"评分项分值由 5 分调整为 8 分;<br/>3. 开标地点不变。</p>', '中国政府采购网', '2026-09-07 08:10:00', '', '', b'0', 0),
(4, '中国移动某省公司 2026-2028 年通信工程建设项目集中采购招标公告', 'tender', '浙江省', '杭州市', '通信工程', 98000.00, '中国移动通信集团浙江有限公司', '中通服咨询设计研究院有限公司', '王工', '0571-86661122', '<h3>项目概况</h3><p>本次集中采购涉及全省 11 个地市的通信管道施工、传输线路建设及机房配套改造,分为 5 个标包,投标人可兼投但不兼得。</p>', '中国招标投标公共服务平台', '2026-09-06 17:20:00', '', '', b'0', 0),
(5, '某县 2026 年高标准农田建设项目(第三批)施工标段招标公告', 'tender', '河南省', '南阳市', '农业水利', 4300.00, '南阳市农业农村局', '河南豫信招标有限责任公司', '刘工', '0377-63332255', '<h3>招标范围</h3><p>项目区土地平整 5200 亩,新建灌溉机井 86 眼,配套输水管道 42 公里,田间道路 18 公里。工期 120 日历天。</p>', '河南省公共资源交易平台', '2026-09-06 16:40:00', '', '', b'0', 0),
(6, '青岛市地铁 9 号线一期工程机电安装标段中标结果公告', 'win', '山东省', '青岛市', '轨道交通', 21500.00, '青岛地铁集团有限公司', '青岛利安建设咨询有限公司', '孙总', '0532-80992211', '<p>中标人:<strong>中建安装集团有限公司</strong>,中标金额 21478 万元,工期 550 日历天。</p>', '山东省公共资源交易网', '2026-09-06 15:05:00', '', '', b'0', 0),
(7, '某国防科技大学光电实验平台设备购置项目采购公告', 'explore', '湖南省', '长沙市', '科研设备', 980.00, '某高校', '湖南中联招标代理有限公司', '陈老师', '0731-84551122', '<h3>采购内容</h3><p>高精度激光干涉仪 2 套、光电成像系统 1 套、高速采集卡 8 块。预算 980 万元。</p>', '中国政府采购网', '2026-09-06 11:00:00', '', '', b'0', 0),
(8, '某省高速公路改扩建工程特许经营社会资本方招标公告', 'tender', '四川省', '成都市', '交通公路', 520000.00, '四川省交通运输厅', '四川公路桥梁建设咨询公司', '周工', '028-85223377', '<h3>项目概况</h3><p>本项目采用"特许经营 + 政府付费"模式,全长 96 公里,双向八车道,建设期 4 年,经营期 25 年。</p>', '四川省公共资源交易平台', '2026-09-05 18:30:00', '', '', b'0', 0),
(9, '西部某某大数据产业园数据中心(一期)机电配套工程招标公告', 'tender', '陕西省', '西安市', '智慧城市', 18600.00, '陕西秦云数据产业发展有限公司', '西部项目管理咨询有限公司', '高工', '029-85225511', '<h3>招标范围</h3><p>数据中心 1 号楼与 2 号楼的机电安装工程,含变配电、UPS、冷水机组、精密空调、动环监控系统安装调试(3000 机柜规模)。</p>', '陕西采购与招标网', '2026-09-05 15:45:00', '', '', b'0', 0),
(10, '某河道水环境综合治理项目 EPC 总承包中标公示', 'win', '江苏省', '苏州市', '生态环保', 7600.00, '苏州市水务局', '江苏苏咨工程咨询有限公司', '钱工', '0512-68771122', '<p>中标人:<strong>中国电建集团华东勘测设计研究院有限公司</strong>(牵头人)与江苏苏建建设工程有限公司联合体,中标金额 7421 万元。</p>', '江苏省公共资源交易网', '2026-09-05 10:15:00', '', '', b'0', 0),
(11, '某职业技术学院新校区二期建设工程总承包招标公告', 'tender', '安徽省', '合肥市', '建筑工程', 32000.00, '合肥职业技术学院', '安徽安天利信工程管理股份有限公司', '吴老师', '0551-63791122', '<h3>建设规模</h3><p>新校区二期总建筑面积 9.2 万平方米,含综合实训楼、学生宿舍、风雨操场、地下车库及室外配套工程。</p>', '合肥公共资源交易网', '2026-09-04 16:20:00', '', '', b'0', 0),
(12, '某光伏电站 100MW 项目逆变器设备采购变更公告', 'change', '青海省', '西宁市', '新能源', 2800.00, '青海绿能新能源有限公司', '青海电力招标咨询有限公司', '马经理', '0971-6335123', '<h3>变更内容</h3><p>逆变器技术要求变更:组串式逆变器单机功率由 ≤176kW 调整为 ≤220kW,容配化比例 1.2:1。投标文件递交截止时间顺延至 2026 年 9 月 18 日。</p>', '青海省公共资源交易网', '2026-09-04 14:00:00', '', '', b'0', 0),
(13, '某市公安局智慧安防小区建设项目中标结果公告', 'win', '北京市', '北京市', '公共安全', 5600.00, '北京市公安局', '北京国际招标有限公司', '崔主任', '010-65518322', '<p>中标人:<strong>北京电通安防科技有限公司</strong>,中标金额 5432 万元,供货期 90 天。</p>', '中国政府采购网', '2026-09-04 09:30:00', '', '', b'0', 0),
(14, '某自贸区 2026 年新建排水管网及窨井改造工程施工招标', 'tender', '福建省', '厦门市', '市政工程', 6800.00, '厦门城建集团', '福建建融工程咨询有限公司', '林工', '0592-2660112', '<h3>项目概况</h3><p>新建 DN400-DN1200 雨水管 12.6 公里,改造老旧窨井 480 座,配套泵站 2 座。工期 240 日历天。</p>', '厦门市公共资源交易网', '2026-09-03 17:00:00', '', '', b'0', 0),
(15, '某银行软件开发中心外部采购——核心系统数字化能力提升项目招标公告', 'tender', '上海市', '上海市', '软件服务', 1500.00, '某股份制银行上海软件开发中心', '上海浦成建设招标咨询有限公司', '朱经理', '021-58881234', '<h3>服务内容</h3><p>核心系统微服务化改造咨询、分布式数据库迁移实施、自动化测试平台建设,服务期 12 个月。</p>', '上海政府采购网', '2026-09-03 13:40:00', '', '', b'0', 0),
(16, '某县城乡供水一体化项目(一期)设备采购中标候选人公示', 'win', '江西省', '九江市', '农业水利', 3900.00, '九江市水利局', '江西明正招标咨询有限公司', '桂工', '0792-8225117', '<p>第一中标候选人:<strong>上海熊猫机械(集团)有限公司</strong>,投标报价 3715 万元。</p>', '江西省公共资源交易网', '2026-09-03 10:20:00', '', '', b'0', 0),
(17, '某学校食堂大宗食材(米面油等)供应商采购公告', 'explore', '广西壮族自治区', '南宁市', '机关团体', 620.00, '南宁市第二中学', '广西嘉华工程咨询有限公司', '覃老师', '0771-3120233', '<h3>采购内容</h3><p>大米、食用油、面粉、调味品一批,服务期一年(2026 年 10 月—2027 年 9 月)。</p>', '广西壮族自治区政府采购网', '2026-09-02 16:30:00', '', '', b'0', 0),
(18, '某国际机场 T3 航站楼改扩建工程地质勘察服务招标公告', 'tender', '云南省', '昆明市', '咨询服务', 1500.00, '昆明长水国际机场', '云南昇腾招标有限公司', '洪工程师', '0871-67121199', '<h3>项目概况</h3><p>T3 航站楼改扩建勘察钻孔约 420 个,需提交岩土工程勘察报告、地基地震评价与沉降分析。</p>', '云南省公共资源交易网', '2026-09-02 11:15:00', '', '', b'0', 0),
(19, '某天然气管道工程一标段钢管采购中标结果公告', 'win', '内蒙古自治区', '鄂尔多斯市', '能源化工', 12800.00, '鄂尔多斯市中浩能源有限公司', '内蒙古蒙正招标有限公司', '敖先生', '0477-3890002', '<p>中标人:<strong>宝鸡石油钢管有限责任公司</strong>,中标金额 12736 万元。</p>', '内蒙古公共资源交易网', '2026-09-02 09:05:00', '', '', b'0', 0),
(20, '某省级政务云平台扩容升级项目公开招标公告', 'tender', '贵州省', '贵阳市', '软件服务', 8600.00, '贵州省大数据发展管理局', '贵州聚力项目管理有限公司', '陈老师', '0851-86993122', '<h3>采购内容</h3><p>政务云平台计算节点扩容 2000 核、存储扩容 2PB,政务数据治理服务及安全防护提升,服务期 24 个月。</p>', '贵州省政府采购网', '2026-09-01 14:50:00', '', '', b'0', 0);

